    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            return current.length > 0 ? String(current[0]) : defaultValue;
        }
        return String(current);
    }

    function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);

        if (!valueMainDisplay) return;

        let numericValue = parseFloat(SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min)));
        valueMainDisplay.innerText = String(Math.round(numericValue));

        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            progressBar.style.backgroundColor = color || 'var(--accent-highlight)';
        }
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                 return;
            }

            if (characterData.hasOwnProperty("丘迟迟")) {
                updateProgressBar('chichi-affection-bar', 'chichi-affection', 'chichi-affection-desc', SafeGetValue(characterData, '丘迟迟.亲密度'), -100, 100, 'var(--chichi-primary)');
                updateProgressBar('chichi-trust-bar', 'chichi-trust', 'chichi-trust-desc', SafeGetValue(characterData, '丘迟迟.信赖度'), 0, 100, 'var(--chichi-secondary)');
            }

            if (characterData.hasOwnProperty("陈快快")) {
                updateProgressBar('kuaikuai-affection-bar', 'kuaikuai-affection', 'kuaikuai-affection-desc', SafeGetValue(characterData, '陈快快.亲密度'), -100, 100, 'var(--kuaikuai-primary)');
                updateProgressBar('kuaikuai-alertness-bar', 'kuaikuai-alertness', 'kuaikuai-alertness-desc', SafeGetValue(characterData, '陈快快.警惕度'), 0, 100, 'var(--kuaikuai-secondary)');
                updateProgressBar('kuaikuai-possessiveness-bar', 'kuaikuai-possessiveness', 'kuaikuai-possessiveness-desc', SafeGetValue(characterData, '陈快快.独占欲'), 0, 100, 'var(--kuaikuai-primary)');
            }

            if (characterData.hasOwnProperty("商甜甜")) {
                updateProgressBar('tiantian-affection-bar', 'tiantian-affection', 'tiantian-affection-desc', SafeGetValue(characterData, '商甜甜.亲密度'), -100, 100, 'var(--tiantian-primary)');
                updateProgressBar('tiantian-dependence-bar', 'tiantian-dependence', 'tiantian-dependence-desc', SafeGetValue(characterData, '商甜甜.依赖度'), 0, 100, 'var(--tiantian-secondary)');
                updateProgressBar('tiantian-crisis-bar', 'tiantian-crisis', 'tiantian-crisis-desc', SafeGetValue(characterData, '商甜甜.危机感'), 0, 100, 'var(--tiantian-primary)');
            }

            if (characterData.hasOwnProperty("世界")) {
                const dateEl = document.getElementById('world-date');
                const dayEl = document.getElementById('world-day');
                const timeEl = document.getElementById('world-time');

                // 更新顶部主状态栏
                if (dateEl) dateEl.innerText = SafeGetValue(characterData, '世界.当前日期');
                if (dayEl) dayEl.innerText = SafeGetValue(characterData, '世界.当前星期');
                if (timeEl) timeEl.innerText = SafeGetValue(characterData, '世界.当前时间');
            }

        } catch (error) {
            const card = document.getElementById('status-card');
            if (card) card.innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
        arrow.innerText = isExpanded ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
