            if (characterData.hasOwnProperty("商甜甜")) {
                updateProgressBar('tiantian-affection-bar', 'tiantian-affection', 'tiantian-affection-desc', SafeGetValue(characterData, '商甜甜.亲密度'), -100, 100, 'var(--tiantian-primary)');
                updateProgressBar('tiantian-dependence-bar', 'tiantian-dependence', 'tiantian-dependence-desc', SafeGetValue(characterData, '商甜甜.依赖度'), 0, 100, 'var(--tiantian-secondary)');
                updateProgressBar('tiantian-crisis-bar', 'tiantian-crisis', 'tiantian-crisis-desc', SafeGetValue(characterData, '商甜甜.危机感'), 0, 100, 'var(--tiantian-primary)');
            }

            if (characterData.hasOwnProperty("世界")) {
                const dateEl = document.getElementById('world-date');
                const dayEl = document.getElementById('world-day');
                const timeEl = document.getElementById('world-time');

                // 更新顶部主状态栏
                if (dateEl) dateEl.innerText = SafeGetValue(characterData, '世界.当前日期');
                if (dayEl) dayEl.innerText = SafeGetValue(characterData, '世界.当前星期');
                if (timeEl) timeEl.innerText = SafeGetValue(characterData, '世界.当前时间');
